      450:     TIFF *tif = img->tif;
      451:     ImageIterTileSeparateRoutine callback = img->callback.separate;
      452:     uint16_t orientation;
      453:     u_char *buf;
      454:     u_char *r, *g, *b, *a;
      455:     uint32_t row, nrow;
      456:     tsize_t scanline;
      457:     uint32_t rowsperstrip;
      458:     uint32_t imagewidth = img->width;
      459:     tsize_t stripsize;
      460:     int32_t fromskew;
      461:     int alpha = img->alpha;
      462: 
      463:     stripsize = TIFFStripSize(tif);
>>>   464:     r = buf = (u_char *)_TIFFmalloc(4 * stripsize);
      465:     if (buf == 0)
      466:     {
      467:         TIFFErrorExtR(tif, TIFFFileName(tif), "No space for tile buffer");
      468:         return (0);
      469:     }
      470:     g = r + stripsize;
      471:     b = g + stripsize;
      472:     a = b + stripsize;
      473:     if (!alpha)
      474:         memset(a, 0xff, stripsize);
      475:     orientation = img->orientation;
      476:     TIFFGetFieldDefaulted(tif, TIFFTAG_ROWSPERSTRIP, &rowsperstrip);
      477:     scanline = TIFFScanlineSize(tif);
      478:     fromskew = (w < imagewidth ? imagewidth - w : 0);
      479:     for (row = 0; row < h; row += rowsperstrip)
      480:     {
      481:         nrow = (row + rowsperstrip > h ? h - row : rowsperstrip);
      482:         if (TIFFReadEncodedStrip(tif, TIFFComputeStrip(tif, row, 0), r,
      483:                                  nrow * scanline) < 0 &&
      484:             img->stoponerr)
      485:             break;
      486:         if (TIFFReadEncodedStrip(tif, TIFFComputeStrip(tif, row, 1), g,
      487:                                  nrow * scanline) < 0 &&
      488:             img->stoponerr)
      489:             break;
      490:         if (TIFFReadEncodedStrip(tif, TIFFComputeStrip(tif, row, 2), b,
      491:                                  nrow * scanline) < 0 &&
      492:             img->stoponerr)
      493:             break;
      494:         if (alpha && (TIFFReadEncodedStrip(tif, TIFFComputeStrip(tif, row, 3),
      495:                                            a, nrow * scanline) < 0 &&
      496:                       img->stoponerr))
      497:             break;
      498:         (*callback)(img, udata, 0, row, w, nrow, fromskew, r, g, b, a);
